fn native_collections_empty_map(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    if let Some(v) = collections_empty_singleton(ctx, "EMPTY_MAP") {
        return Ok(Some(v));
    }
    // Fallback (field not yet initialised): fresh synthetic empty map.
    let map = alloc_backing_map(ctx);
    native_map_init(ctx, &[Value::Object(Some(map))])?;
    Ok(Some(Value::Object(Some(map))))
}

fn native_collections_empty_set(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    if let Some(v) = collections_empty_singleton(ctx, "EMPTY_SET") {
        return Ok(Some(v));
    }
    // Fallback (field not yet initialised): fresh synthetic empty set.
    let set = alloc_synthetic(ctx, "java/util/HashSet", HS_NUM_FIELDS);
    let inner_map = alloc_backing_map(ctx);
    native_map_init(ctx, &[Value::Object(Some(inner_map))])?;
    ctx.set_field(set, HS_FIELD_MAP, Value::Object(Some(inner_map)));
    Ok(Some(Value::Object(Some(set))))
}

fn native_collections_empty_iterator(
    ctx: &mut dyn NativeContext,
    _args: &[Value],
) -> MethodCallResult {
    let arr = alloc_ref_array(ctx, 0);
    let itr = alloc_synthetic(ctx, "java/util/Collections$EmptyItr", 2);
    ctx.set_field(itr, 0, Value::Object(Some(arr)));
    ctx.set_field(itr, 1, Value::Int(0));
    Ok(Some(Value::Object(Some(itr))))
}

fn native_collections_singleton(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let elem = args.first().cloned().unwrap_or(Value::Object(None));
    if let Some(set) = alloc_real_jdk(ctx, "java/util/Collections$SingletonSet") {
        ctx.set_field_by_name(set, "element", elem);
        return Ok(Some(Value::Object(Some(set))));
    }
    let set = alloc_synthetic(ctx, "java/util/HashSet", HS_NUM_FIELDS);
    let inner_map = alloc_backing_map(ctx);
    native_map_init(ctx, &[Value::Object(Some(inner_map))])?;
    ctx.set_field(set, HS_FIELD_MAP, Value::Object(Some(inner_map)));
    // Add elem
    native_map_put(
        ctx,
        &[Value::Object(Some(inner_map)), elem, Value::Object(None)],
    )?;
    Ok(Some(Value::Object(Some(set))))
}

fn native_collections_singleton_map(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let key = args.first().cloned().unwrap_or(Value::Object(None));
    let val = args.get(1).cloned().unwrap_or(Value::Object(None));
    if let Some(map) = alloc_real_jdk(ctx, "java/util/Collections$SingletonMap") {
        ctx.set_field_by_name(map, "k", key);
        ctx.set_field_by_name(map, "v", val);
        return Ok(Some(Value::Object(Some(map))));
    }
    let map = alloc_backing_map(ctx);
    native_map_init(ctx, &[Value::Object(Some(map))])?;
    native_map_put(ctx, &[Value::Object(Some(map)), key, val])?;
    Ok(Some(Value::Object(Some(map))))
}

fn native_collections_frequency(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let coll = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let mut target = args.get(1).cloned().unwrap_or(Value::Object(None));
    let (data, size) = al_state(ctx, coll);
    // Stub-removal wave 2 (2026-07-28): `al_state` only understands the
    // ArrayList shape (field 0 = backing array, field 1 = size). EVERY other
    // Collection — `Arrays.asList` (an `Arrays$ArrayList`), `HashSet`,
    // `LinkedList`, any user Collection — fell into the `None` arm and
    // reported frequency 0, i.e. "this element does not occur", for a
    // collection full of matches. Measured against HotSpot 25:
    // Arrays.asList 3 -> 0, HashSet 1 -> 0, LinkedList 2 -> 0.
    // Drive the receiver's own `toArray()` instead; every Collection has one.
    let (data, size) = match data {
        Some(d) => (d, size),
        None => {
            let coll_pin = ctx.pin_native_root(coll);
            let target_pin = pin_value(ctx, target);
            let arr = ctx.invoke_virtual(coll, "toArray", "()[Ljava/lang/Object;", &[])?;
            target = read_pinned_elem(ctx, target_pin, target);
            ctx.unpin_native_roots(coll_pin);
            match arr {
                Some(Value::Object(Some(a))) => {
                    let n = ctx.array_length(a) as i32;
                    (a, n)
                }
                _ => return Ok(Some(Value::Int(0))),
            }
        }
    };
    // Family-1 fix (cce0079): pinned scan (counts every match, so no
    // early-exit helper).
    let data_pin = ctx.pin_native_root(data);
    let th = pin_value(ctx, target);
    let mut data = data;

    let mut count = 0i32;
    for i in 0..size as usize {
        let elem = ctx.get_array_element(data, i);
        let matched = list_element_matches(ctx, &elem, &target);
        data = ctx.read_native_pin(data_pin, data);
        target = read_pinned_elem(ctx, th, target);
        if matched {
            count += 1;
        }
    }
    ctx.unpin_native_roots(data_pin);
    Ok(Some(Value::Int(count)))
}

// Retained for reference only — no longer registered (see the note at the
// `Collections` registration site); the real JDK bytecode handles `disjoint`.
#[allow(dead_code)]
fn native_collections_disjoint(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let c1 = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(1))),
    };
    let c2 = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(1))),
    };
    let (data1, size1) = al_state(ctx, c1);
    let (data2, size2) = al_state(ctx, c2);
    let (d1, d2) = match (data1, data2) {
        (Some(a), Some(b)) => (a, b),
        _ => return Ok(Some(Value::Int(1))),
    };
    for i in 0..size1 as usize {
        let elem = ctx.get_array_element(d1, i);
        for j in 0..size2 as usize {
            let other = ctx.get_array_element(d2, j);
            if values_equal(ctx, &elem, &other) {
                return Ok(Some(Value::Int(0)));
            }
        }
    }
    Ok(Some(Value::Int(1)))
}

/// `Collections.max(Collection)` / `Collections.min(Collection)` share this
/// natural-ordering scan: pick element 0, then walk the rest comparing via
/// `Comparable.compareTo` (the real JDK contract — `max`/`min` are literally
/// specified in terms of `compareTo`), replacing the running candidate when
/// `cmp() > 0` (max) or `cmp() < 0` (min). Ties keep the earliest element,
/// matching `Collections.max`/`min`'s documented "first of equal maximums"
/// behavior.
///
/// The previous implementation compared `val_to_string(elem)` — i.e. each
/// element's `read_string()` decode — which only means something for actual
/// `java.lang.String` elements. For any other `Comparable` (e.g. a
/// `DeadNode`/custom class), `read_string` returns `None` for a non-String
/// object, so every element degraded to the same empty string and the `>`/`<`
/// comparison was *always false* — silently returning element 0 regardless of
/// true ordering. That produced a deterministic-but-wrong "minimum" for
/// `RestClient.selectNodes`'s `Collections.min(selectedDeadNodes)` dead-host
/// revival pick, always resurrecting the first-registered host instead of the
/// one with the lowest `deadUntilNanos` (RestClientMultipleHostsTests.
/// testRoundRobinRetryErrors: "host [...] not found, most likely used
/// multiple times").
fn native_collections_extreme(
    ctx: &mut dyn NativeContext,
    args: &[Value],
    want_max: bool,
) -> MethodCallResult {
    let coll = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let (data, size) = al_state(ctx, coll);
    let elems = if let Some(data) = data {
        let len = size.max(0) as usize;
        let mut out = Vec::with_capacity(len);
        for i in 0..len {
            out.push(ctx.get_array_element(data, i));
        }
        out
    } else {
        collect_collection_elements_or_real(ctx, coll)
    };
    if elems.is_empty() {
        return Err(
            cratonvm_types::error::RuntimeError::NoSuchElementException {
                message: String::new(),
            }
            .into(),
        );
    }
    // cceres3: pin across GC-capable call (stream stale-at-store wave) — the
    // compareTo dispatch re-enters Java, moving `best` and every later elem;
    // track `best` by handle like native_stream_min does.
    let (elem_base, elem_handles) = pin_value_slice(ctx, &elems);
    let mut best = elems[0];
    let mut best_handle = elem_handles[0];
    for i in 1..elems.len() {
        let elem = read_pinned_elem(ctx, elem_handles[i], elems[i]);
        let best_arg = read_pinned_elem(ctx, best_handle, best);
        let cmp = match compare_via_compare_to(ctx, &elem, &best_arg) {
            Ok(c) => c,
            Err(e) => {
                if elem_base != usize::MAX {
                    ctx.unpin_native_roots(elem_base);
                }
                return Err(e);
            }
        };
        if (want_max && cmp > 0) || (!want_max && cmp < 0) {
            best = elems[i];
            best_handle = elem_handles[i];
        }
    }
    let best = read_pinned_elem(ctx, best_handle, best);
    if elem_base != usize::MAX {
        ctx.unpin_native_roots(elem_base);
    }
    Ok(Some(best))
}

fn native_collections_max(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    native_collections_extreme(ctx, args, true)
}

fn native_collections_min(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    native_collections_extreme(ctx, args, false)
}

fn native_collections_swap(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let list = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let i = match args.get(1) {
        Some(Value::Int(v)) => *v as usize,
        _ => return Ok(None),
    };
    let j = match args.get(2) {
        Some(Value::Int(v)) => *v as usize,
        _ => return Ok(None),
    };
    let (data, _) = al_state(ctx, list);
    if let Some(d) = data {
        let a = ctx.get_array_element(d, i);
        let b = ctx.get_array_element(d, j);
        ctx.set_array_element(d, i, b);
        ctx.set_array_element(d, j, a);
    }
    Ok(None)
}

fn native_collections_fill(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let list = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let val = args.get(1).cloned().unwrap_or(Value::Object(None));
    let (data, size) = al_state(ctx, list);
    if let Some(d) = data {
        for i in 0..size as usize {
            ctx.set_array_element(d, i, val);
        }
    }
    Ok(None)
}

fn native_collections_n_copies(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let n = match args.first() {
        Some(Value::Int(v)) => *v,
        _ => 0,
    };
    let val = args.get(1).cloned().unwrap_or(Value::Object(None));
    let __al_n_fields = al_slots(ctx).2;
    // cceres3: pin across GC-capable call (stream stale-at-store wave) — the
    // two allocations can move `val` and the freshly allocated `list`.
    let val_handle = pin_value(ctx, val);
    let list = alloc_synthetic(ctx, "java/util/ArrayList", __al_n_fields);
    let list_pin = ctx.pin_native_root(list);
    let arr = alloc_ref_array(ctx, n.max(0) as usize);
    let val = read_pinned_elem(ctx, val_handle, val);
    for i in 0..n.max(0) as usize {
        ctx.set_array_element(arr, i, val);
    }
    let list = ctx.read_native_pin(list_pin, list);
    al_set_data(ctx, list, arr);
    al_set_size(ctx, list, n.max(0));
    ctx.unpin_native_roots(if val_handle == usize::MAX {
        list_pin
    } else {
        val_handle
    });
    Ok(Some(Value::Object(Some(list))))
}

fn native_collections_shuffle(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let list = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let (data, size) = al_state(ctx, list);
    if let Some(d) = data {
        let n = size as usize;
        // Simple Fisher-Yates using system time as seed
        let seed = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(42u64, |t| t.as_nanos() as u64);
        let mut rng = seed;
        for i in (1..n).rev() {
            rng = rng
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            let j = (rng >> 33) as usize % (i + 1);
            let a = ctx.get_array_element(d, i);
            let b = ctx.get_array_element(d, j);
            ctx.set_array_element(d, i, b);
            ctx.set_array_element(d, j, a);
        }
    }
    Ok(None)
}

fn native_collections_add_all(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let coll = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let elements = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    // Every `Collection.add` dispatch can execute arbitrary Java code and
    // collect. Root both the destination and the source array before the first
    // callback, then refresh them for every iteration. Keeping the array as a
    // raw entry-argument copy made the second element read dereference
    // from-space during WildFly's parallel subsystem boot.
    let pin_base = ctx.pin_native_root(coll);
    let elements_pin = ctx.pin_native_root(elements);
    let elements = ctx.read_native_pin(elements_pin, elements);
    let len = ctx.array_length(elements);
    let mut modified = false;
    for i in 0..len {
        let elements = ctx.read_native_pin(elements_pin, elements);
        let elem = ctx.get_array_element(elements, i);
        // Dispatch to the target collection's real `add` instead of
        // hard-coding `native_al_add` (the ArrayList `elementData`/`size`
        // layout). `Collections.addAll` accepts any `Collection` — a
        // HashSet, LinkedList, TreeSet, etc. store elements nothing like
        // ArrayList, so `native_al_add` would write the wrong fields and
        // silently drop every element. JVMS/JDK spec is `result |=
        // c.add(element)`; honour that via virtual dispatch.
        let coll = ctx.read_native_pin(pin_base, coll);
        match ctx.invoke_virtual(coll, "add", "(Ljava/lang/Object;)Z", &[elem]) {
            Ok(Some(Value::Int(1))) => modified = true,
            Ok(_) => {}
            Err(error) => {
                ctx.unpin_native_roots(pin_base);
                return Err(error);
            }
        }
    }
    ctx.unpin_native_roots(pin_base);
    Ok(Some(Value::Int(if modified { 1 } else { 0 })))
}

// ===========================================================================
// Phase 41: BlockingQueue family — LinkedBlockingQueue, ArrayBlockingQueue
// ===========================================================================

// LinkedBlockingQueue = 4-field synthetic (same as LinkedList + capacity)
const LBQ_FIELD_HEAD: usize = 0; // Object[] backing buffer (NOT an index)
const LBQ_FIELD_TAIL: usize = 1; // Int: head index into the backing buffer
const LBQ_FIELD_SIZE: usize = 2;
const LBQ_FIELD_CAPACITY: usize = 3;
const _LBQ_NUM_FIELDS: usize = 4;

// ---------------------------------------------------------------------------
// FIFO layout (perf P1 fix): the backing `Object[]` (in LBQ_FIELD_HEAD) holds
// the live elements at indices `[head .. head + size)`, where `head` is the
// integer in LBQ_FIELD_TAIL (previously an unused, always-0 slot). A `poll`
// returns element `head` and advances `head` by one — O(1) — instead of the
// former O(n) left-shift of every remaining element (which made an N-element
// drain O(n^2)). The buffer is a linear (non-wrapping) window that drifts
// rightward as elements are polled; `lbq_ensure_capacity` compacts the window
// back to index 0 (and grows when necessary) before any append, so the tail
// never runs off the end. Logical element `i` therefore lives at array index
// `head + i`.

/// Current head index (offset of logical element 0 within the backing array).
fn lbq_head(ctx: &dyn NativeContext, this: ObjectRef) -> usize {
    match ctx.get_field(this, LBQ_FIELD_TAIL) {
        Value::Int(v) if v >= 0 => v as usize,
        _ => 0,
    }
}

/// Store the head index.
fn lbq_set_head(ctx: &mut dyn NativeContext, this: ObjectRef, head: usize) {
    ctx.set_field(this, LBQ_FIELD_TAIL, Value::Int(head as i32));
}

fn register_blocking_queue_natives(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    // LinkedBlockingQueue
    let lbq = "java/util/concurrent/LinkedBlockingQueue";
    r.register(lbq, "<init>", "()V", native_lbq_init);
    r.register(lbq, "<init>", "(I)V", native_lbq_init_cap);
    // put() blocks until space is available via monitor wait/notify (task #15)
    r.register(lbq, "put", "(Ljava/lang/Object;)V", native_lbq_put_blocking);
    r.register(lbq, "offer", "(Ljava/lang/Object;)Z", native_lbq_offer_bool);
    r.register(lbq, "add", "(Ljava/lang/Object;)Z", native_lbq_offer_bool);
    // take() blocks until an element is available via monitor wait/notify (task #15)
    r.register(
        lbq,
        "take",
        "()Ljava/lang/Object;",
        native_lbq_take_blocking,
    );
    r.register(lbq, "poll", "()Ljava/lang/Object;", native_lbq_poll);
    r.register(lbq, "peek", "()Ljava/lang/Object;", native_lbq_peek);
    r.register(lbq, "size", "()I", native_lbq_size);
    r.register(lbq, "isEmpty", "()Z", native_lbq_is_empty);
    r.register(lbq, "remainingCapacity", "()I", native_lbq_remaining);
    r.register(lbq, "clear", "()V", native_lbq_clear);
    r.register(
        lbq,
        "contains",
        "(Ljava/lang/Object;)Z",
        native_lbq_contains,
    );
    r.register(lbq, "remove", "(Ljava/lang/Object;)Z", native_lbq_remove);
    r.register(lbq, "toArray", "()[Ljava/lang/Object;", native_lbq_to_array);
    r.register(
        lbq,
        "iterator",
        "()Ljava/util/Iterator;",
        native_lbq_iterator,
    );
    // Also register under BlockingQueue interface
    let bq = "java/util/concurrent/BlockingQueue";
    r.register(bq, "put", "(Ljava/lang/Object;)V", native_lbq_put_blocking);
    r.register(bq, "offer", "(Ljava/lang/Object;)Z", native_lbq_offer_bool);
    r.register(bq, "take", "()Ljava/lang/Object;", native_lbq_take_blocking);
    r.register(bq, "poll", "()Ljava/lang/Object;", native_lbq_poll);
    r.register(bq, "peek", "()Ljava/lang/Object;", native_lbq_peek);

    // ArrayBlockingQueue
    let abq = "java/util/concurrent/ArrayBlockingQueue";
    r.register(abq, "<init>", "(I)V", native_abq_init);
    r.register(abq, "<init>", "(IZ)V", native_abq_init_fair);
    r.register(abq, "put", "(Ljava/lang/Object;)V", native_lbq_put_blocking);
    r.register(abq, "offer", "(Ljava/lang/Object;)Z", native_lbq_offer_bool);
    r.register(abq, "add", "(Ljava/lang/Object;)Z", native_lbq_offer_bool);
    r.register(
        abq,
        "take",
        "()Ljava/lang/Object;",
        native_lbq_take_blocking,
    );
    r.register(abq, "poll", "()Ljava/lang/Object;", native_lbq_poll);
    r.register(abq, "peek", "()Ljava/lang/Object;", native_lbq_peek);
    r.register(abq, "size", "()I", native_lbq_size);
    r.register(abq, "isEmpty", "()Z", native_lbq_is_empty);
    r.register(abq, "remainingCapacity", "()I", native_lbq_remaining);
    r.register(abq, "clear", "()V", native_lbq_clear);
    r.register(
        abq,
        "contains",
        "(Ljava/lang/Object;)Z",
        native_lbq_contains,
    );
    r.register(abq, "remove", "(Ljava/lang/Object;)Z", native_lbq_remove);
    r.register(abq, "toArray", "()[Ljava/lang/Object;", native_lbq_to_array);
    r.register(
        abq,
        "iterator",
        "()Ljava/util/Iterator;",
        native_lbq_iterator,
    );

    // ConcurrentLinkedQueue — thread-safety wrappers (round-5 Fix 2 HIGH).
    //
    // The raw `native_lbq_offer_bool` / `native_lbq_poll` do unsynchronised
    // array shifts that corrupt under concurrent producer+consumer load
    // (read-modify-write of LBQ_FIELD_SIZE races; element-shift in `poll`
    // races against `offer` appending at `size`). Real CLQ is lock-free
    // (Michael-Scott queue); we approximate the *correctness* guarantee
    // by serialising every op on the `this` monitor. Not lock-free in
    // throughput, but at least no torn updates.
    let clq = "java/util/concurrent/ConcurrentLinkedQueue";
    r.register(clq, "<init>", "()V", native_lbq_init);
    r.register(clq, "offer", "(Ljava/lang/Object;)Z", native_clq_offer);
    r.register(clq, "add", "(Ljava/lang/Object;)Z", native_clq_offer);
    r.register(clq, "poll", "()Ljava/lang/Object;", native_clq_poll);
    r.register(clq, "peek", "()Ljava/lang/Object;", native_clq_peek);
    r.register(clq, "size", "()I", native_lbq_size);
    r.register(clq, "isEmpty", "()Z", native_lbq_is_empty);
    r.register(
        clq,
        "contains",
        "(Ljava/lang/Object;)Z",
        native_lbq_contains,
    );
    r.register(clq, "remove", "(Ljava/lang/Object;)Z", native_lbq_remove);
    r.register(
        clq,
        "iterator",
        "()Ljava/util/Iterator;",
        native_lbq_iterator,
    );

    // ConcurrentLinkedDeque — same synchronisation rationale as CLQ.
    let cld = "java/util/concurrent/ConcurrentLinkedDeque";
    r.register(cld, "<init>", "()V", native_lbq_init);
    r.register(
        cld,
        "offerFirst",
        "(Ljava/lang/Object;)Z",
        native_cld_offer_first,
    );
    r.register(cld, "offerLast", "(Ljava/lang/Object;)Z", native_clq_offer);
    r.register(cld, "pollFirst", "()Ljava/lang/Object;", native_clq_poll);
    r.register(
        cld,
        "pollLast",
        "()Ljava/lang/Object;",
        native_cld_poll_last,
    );
    r.register(cld, "peekFirst", "()Ljava/lang/Object;", native_clq_peek);
    r.register(
        cld,
        "peekLast",
        "()Ljava/lang/Object;",
        native_cld_peek_last,
    );
    r.register(cld, "size", "()I", native_lbq_size);
    r.register(cld, "isEmpty", "()Z", native_lbq_is_empty);
    r.register(
        cld,
        "iterator",
        "()Ljava/util/Iterator;",
        native_lbq_iterator,
    );
    r.set_category(__prev_cat);
}

// ---------------------------------------------------------------------------
// Round-5 Fix 2 (HIGH): synchronised CLQ/CLD wrappers
// ---------------------------------------------------------------------------
//
// Real JDK ConcurrentLinkedQueue/Deque are lock-free (Michael-Scott /
// concurrent doubly-linked-list). Our synthetic backing is an ArrayList,
// which the LBQ helpers mutate with unsynchronised read-modify-write
// sequences. Producer+consumer racing would tear the size counter and
// drop or duplicate elements.
//
// These wrappers acquire the `this`-object monitor around each op so the
// observable behaviour is serialisable. monitor_enter/exit on `this` is
// also what real JDK code would synchronise on for
// `Collections.synchronizedQueue(queue)`, so semantically identical from
// the bytecode side. NOT lock-free in the throughput sense; treat as a
// correctness-only stopgap until a real Michael-Scott port lands.

#[cfg(not(feature = "synthetic-jdk"))]
fn register_linked_blocking_deque_stub_natives(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::SyntheticStub);
    let lbd = "java/util/concurrent/LinkedBlockingDeque";
    r.register(lbd, "<init>", "()V", native_lbq_init);
    r.register(lbd, "offer", "(Ljava/lang/Object;)Z", native_clq_offer);
    r.register(lbd, "add", "(Ljava/lang/Object;)Z", native_clq_offer);
    r.register(
        lbd,
        "offerFirst",
        "(Ljava/lang/Object;)Z",
        native_cld_offer_first,
    );
    r.register(lbd, "offerLast", "(Ljava/lang/Object;)Z", native_clq_offer);
    r.register(lbd, "poll", "()Ljava/lang/Object;", native_clq_poll);
    r.register(lbd, "pollFirst", "()Ljava/lang/Object;", native_clq_poll);
    r.register(
        lbd,
        "pollLast",
        "()Ljava/lang/Object;",
        native_cld_poll_last,
    );
    r.register(lbd, "peek", "()Ljava/lang/Object;", native_clq_peek);
    r.register(lbd, "peekFirst", "()Ljava/lang/Object;", native_clq_peek);
    r.register(
        lbd,
        "peekLast",
        "()Ljava/lang/Object;",
        native_cld_peek_last,
    );
    r.register(lbd, "size", "()I", native_lbq_size);
    r.register(lbd, "isEmpty", "()Z", native_lbq_is_empty);
    r.register(lbd, "clear", "()V", native_lbq_clear);
    r.register(
        lbd,
        "iterator",
        "()Ljava/util/Iterator;",
        native_lbq_iterator,
    );
    r.set_category(__prev_cat);
}

